#include "runtime_diagnostics.h"
#include <windows.h>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace moon::diagnostics;
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("Explicit isolated test root required");const auto root=std::filesystem::absolute(std::filesystem::u8path(argv[1]))/("owned-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));if(std::filesystem::exists(root))throw std::runtime_error("Test root must be new");std::filesystem::create_directories(root);std::ofstream(root/"test-owned.marker")<<"native diagnostic fixture";auto check=[](bool b,const char* why){if(!b)throw std::runtime_error(why);};check(ownLogName("native-session-1-2-3.jsonl")&&!ownLogName("session-1.jsonl")&&!ownLogName("notes.jsonl")&&!ownLogName("native-session-foo.jsonl"),"Strict own log namespace");
 {Recorder r(root/"memory/logs",root/"memory/fallback.jsonl",1);for(int i=0;i<220;++i)r.record("session","fixture",{{"i",std::int64_t(i)}});check(r.recentSize()==200&&r.pendingSize()==0,"Memory200 cap and no write queue");check(!std::filesystem::exists(root/"memory/logs"),"Memory mode never creates logs");r.exportSnapshot(root/"memory.json");check(std::filesystem::file_size(root/"memory.json")>0,"Manual memory export");r.mode(0);r.record("error","ignored");check(r.recentSize()==0&&r.pendingSize()==0,"Off clears and stops collection");}
 const auto logs=root/"full/logs";std::filesystem::create_directories(logs);std::ofstream(logs/"notes.jsonl")<<"keep";std::ofstream(logs/"session-legacy.jsonl")<<"keep";for(int i=0;i<10;++i)std::ofstream(logs/("native-session-0-0-"+std::to_string(i)+".jsonl"))<<"{}\n";
 {Recorder r(logs,root/"fallback.jsonl",2);for(int i=0;i<7000;++i){r.record("operation-stage","rotation",{{"body",std::string(500,'a')},{"index",std::int64_t(i)}});if(i%50==49)check(r.flush(),"Flush rotation fixture");}check(r.flush(),"Final flush");check(r.lastError().empty(),"Full persistence succeeded");int count=0;bool rotated=false;for(const auto& f:std::filesystem::directory_iterator(logs))if(ownLogName(f.path().filename().u8string())){++count;check(std::filesystem::file_size(f.path())<=4*1024*1024,"4MiB log bound");if(std::filesystem::file_size(f.path())>1024*1024)rotated=true;}check(count==8&&rotated,"Eight newest native log retention");check(std::filesystem::exists(logs/"notes.jsonl")&&std::filesystem::exists(logs/"session-legacy.jsonl"),"Unrelated and old legacy records preserved");}

 {Recorder r(root/"bounded/logs",root/"bounded-fallback.jsonl",2);for(int i=0;i<2000;++i){r.record("operation-stage","queue.fixture",{{"i",std::int64_t(i)}});check(r.pendingSize()<=500,"Writer pending never exceeds500");}r.record("error","priority.error-survives");check(r.flush(),"Bounded queue settles");bool found=false;for(const auto& f:std::filesystem::directory_iterator(root/"bounded/logs")){std::ifstream in(f.path());std::string content((std::istreambuf_iterator<char>(in)),{});if(content.find("priority.error-survives")!=std::string::npos)found=true;}check(found,"Priority error persisted under queue pressure");}
 const auto blocked=root/"blocked";std::ofstream(blocked)<<"not a directory";
 {Recorder r(blocked,root/"emergency.jsonl",2);std::string original;try{throw std::runtime_error("original-edit-error");}catch(const std::exception& e){original=e.what();r.record("error","original",{{"message",original}});}check(original=="original-edit-error","Diagnostic never replaces original exception");check(r.flush()&&!r.lastError().empty()&&r.hasFallback(),"Write error preserves emergency records");check(std::filesystem::exists(root/"emergency.jsonl"),"Emergency copy persisted");r.exportSnapshot(root/"fallback-export.json",true);}
 {Recorder r(root/"reopened/logs",root/"emergency.jsonl",1);check(r.hasFallback(),"Prior-session fallback retained");}
 std::cout<<"Native diagnostics legacy mode/ring/write/rotation/retention/fallback fixtures passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
